    {'id': 'li_7523795493034926080', 'author': 'Rückenwind mit FiF', 'author_title': 'Netzwerk (Frauen in Führung)', 'source': 'LinkedIn', 'url': 'https://www.linkedin.com/posts/zwischen-ki-agenten-und-echten-begegnungen-ugcPost-7523795493034926080-319V/', 'text': 'Zwischen KI-Agenten und echten Begegnungen. Das FI-Forum 2026 stand unter dem Motto „Heimvorteil“. Masterclass mit Dr. Sarah Brockhoff (zeb) und Paula Menninghaus (Strong Partners) zum weiblichen Faktor in Führung mit KI; S-FiF Lounge als Treffpunkt. Danke an die Finanz Informatik!', 'created_at': '2026-11-04T17:17:10Z', 'likes': 18, 'comments': 5, 'category': 'Side Event', 'sentiment': 'positive', 'confidence': 0.9, 'severity': 'low', 'summary': 'Masterclass Führung & KI, S-FiF Lounge.', 'themes': ['Führung', 'KI', 'Netzwerk'], 'verified': True},
    {'id': 'fb_artecom_pfbid0r6s3RGAp3nU', 'author': 'artecom Veranstaltungs GmbH & Co. KG', 'author_title': 'Unternehmensseite', 'source': 'Facebook', 'url': 'https://www.facebook.com/artecom.event/posts/pfbid0r6s3RGAp3nUUg3AgUcCWba6E3Y9ZFNnASqhkZrRk3EhPX6D5Bz5khvWRosSs2bDyl', 'text': 'Mehr Sichtbarkeit. Mehr Aufmerksamkeit. Mehr Raum für starke Gespräche. Noch bis morgen (5. November) ist die FINMAS GmbH auf dem FI-Forum zu sehen – mit einem Messeauftritt, den wir von Anfang bis Ende konzipiert und gestaltet haben. #fiforum2026', 'created_at': '2026-11-04T17:15:00Z', 'likes': 1, 'comments': 0, 'category': 'Aussteller / Teilnahme', 'sentiment': 'positive', 'confidence': 0.9, 'severity': 'low', 'summary': 'Messebauer artecom zeigt FINMAS-Stand.', 'themes': ['Messedesign', 'Finmas'], 'verified': True},
