    {'id': 'li_7523379956358205441', 'author': 'Julia Kufner', 'author_title': 'Vertriebsinnendienst bei Foconis Analytics GmbH', 'source': 'LinkedIn', 'url': 'https://www.linkedin.com/posts/julia-kufner-558a22341_foconisanalytics-fiforum2026-banken-ugcPost-7523379956358205441-63mG/', 'text': 'Viel Erfolg und viele spannende Gespräche wünsche ich unserem Team von Foconis auf dem FI-Forum 2026! 🍀 Besuchen Sie unsere Kollegen an Stand 12 und erfahren Sie mehr über Foconis-ZAK, PIKSA und weitere Lösungsansätze für die Herausforderungen im Sparkassenumfeld. #FoconisAnalytics #FIForum2026', 'created_at': '2026-11-03T13:45:59Z', 'likes': 0, 'comments': 0, 'category': 'Aussteller / Teilnahme', 'sentiment': 'positive', 'confidence': 0.9, 'severity': 'low', 'summary': 'Foconis an Stand 12 mit Foconis-ZAK und PIKSA.', 'themes': ['Aussteller', 'Stand'], 'verified': True},
    {'id': 'li_7523375207084990464', 'author': 'Ulrike Gruel', 'author_title': 'Head of Product Development | Leiterin Produktentwicklung | Lecturer @FH-Wedel', 'source': 'LinkedIn', 'url': 'https://www.linkedin.com/posts/ulrike-gruel-b2a92b1b6_star-finanz-auf-dem-fi-forum-ugcPost-7523375207084990464-Zh9J/', 'text': 'Star Finanz auf dem FI-Forum.', 'created_at': '2026-11-03T13:27:06Z', 'likes': 0, 'comments': 0, 'category': 'Aussteller / Teilnahme', 'sentiment': 'positive', 'confidence': 0.8, 'severity': 'low', 'summary': 'Star Finanz auf dem FI-Forum (Bildbeitrag).', 'themes': ['Aussteller'], 'verified': True},
    {'id': 'li_7523375004693024768', 'author': 'Sascha Ruh', 'author_title': 'Geschäftsführer Sparkassen Consulting GmbH', 'source': 'LinkedIn', 'url': 'https://www.linkedin.com/posts/sascha-ruh-023412217_fiforum-frankfurt-sparkasse-ugcPost-7523375004693024768-BYyF/', 'text': '82 % der Aufgaben sind automatisierbar. Eine Zahl, die erstmal sitzt. … Aber was bedeutet KI für Sparkassen als Arbeitgeberinnen? Darüber haben Thorsten Bambey, Dirk Buschmann und ich heute auf dem FI-Forum gesprochen. Die entscheidende Frage ist nicht: Wen ersetzt KI? Sondern: Welche Aufgaben müssen Menschen künftig überhaupt noch selbst machen? … weniger Personal und (zu wenig) Nachwuchs, steigende Komplexität und wachsender Effizienzdruck. #FIForum #KünstlicheIntelligenz #Personal', 'created_at': '2026-11-03T13:26:18Z', 'likes': 16, 'comments': 1, 'category': 'Speaker / Vortrag', 'sentiment': 'neutral', 'confidence': 0.85, 'severity': 'low', 'summary': 'Vortrag zu KI und Sparkassen als Arbeitgeber: Automatisierbarkeit, Rollen, Kompetenzen.', 'themes': ['KI', 'Personal', 'Automatisierung'], 'verified': True},
