    {'id': 'li_7523326445390274560', 'author': 'P3N AG', 'author_title': 'Unternehmensseite', 'source': 'LinkedIn', 'url': 'https://www.linkedin.com/posts/treffen-wir-uns-beim-fi-forum-in-frankfurt-share-7523326445390274560-UUyN/', 'text': 'Treffen wir uns beim FI-Forum in Frankfurt? Beim FI-Forum 2026 steht neben technologischen und fachlichen Themen auch der persönliche Austausch innerhalb der Sparkassen-Finanzgruppe im Mittelpunkt. Genau dafür sind unsere Vorstände Thomas Birnstein und Joachim Becker in Frankfurt unterwegs: für Gespräche, neue Kontakte, bekannte Gesichter und den Austausch über die Themen, die Sparkassen aktuell beschäftigen.', 'created_at': '2026-11-03T10:13:21Z', 'likes': 6, 'comments': 2, 'category': 'Aussteller / Teilnahme', 'sentiment': 'positive', 'confidence': 0.93, 'severity': 'low', 'summary': 'P3N-Vorstände in Frankfurt für Gespräche unterwegs.', 'themes': ['Networking', 'Aussteller'], 'verified': True},
    {'id': 'li_7523325771055173632', 'author': 'Maximilian Weiß', 'author_title': 'Sales Manager Strategic Business Development #WirsindWertpapierservice', 'source': 'LinkedIn', 'url': 'https://www.linkedin.com/posts/maximilian-wei%C3%9F-a5ab36236_fiforum-dwpbank-sparkassen-share-7523325771055173632-UBcm/', 'text': 'Altersvorsorgedepot trifft Kryptowährungen – wie bringt die dwpbank beides zusammen? 👀 Die Antwort gibt es auf dem FI-Forum in Frankfurt: an unserem Stand PV12 im Partnervillage! Vom 3. bis 5. November sind wir auf dem FI-Forum in Frankfurt und haben gleich zwei Themen im Gepäck, die das Wertpapiergeschäft der Sparkassen bewegen werden: Altersvorsorgewelt – Vorsorge neu denken. Das Altersvorsorgedepot kommt 2027.', 'created_at': '2026-11-03T10:10:40Z', 'likes': 25, 'comments': 0, 'category': 'Aussteller / Teilnahme', 'sentiment': 'positive', 'confidence': 0.94, 'severity': 'low', 'summary': 'dwpbank an Stand PV12: Altersvorsorgedepot und Krypto.', 'themes': ['Altersvorsorgedepot', 'Krypto', 'Wertpapiere'], 'verified': True},
