    {'id': 'li_7523026959790919680', 'author': 'LSEG Data & Analytics', 'author_title': 'Unternehmensseite', 'source': 'LinkedIn', 'url': 'https://www.linkedin.com/posts/lseg-finanzinformatik-fiforum-share-7523026959790919680-ERxz/', 'text': 'Treffen Sie LSEG beim Finanz Informatik Forum 2026 in Frankfurt! Vom 3.–5. November sind wir vor Ort. Besuchen Sie uns am Stand PV24, lernen Sie unser Team kennen und nutzen Sie die Gelegenheit zum persönlichen Austausch. 3.–5. November 2026 | Messe Frankfurt | LSEG-Stand PV24 #LSEG #FinanzInformatik #FIForum #Frankfurt', 'created_at': '2026-11-02T14:23:18Z', 'likes': 1, 'comments': 0, 'category': 'Aussteller / Teilnahme', 'sentiment': 'positive', 'confidence': 0.87, 'severity': 'low', 'summary': 'LSEG am Stand PV24 vertreten.', 'themes': ['LSEG', 'Partner-Stand'], 'verified': True},
