    {'id': 'li_7522962457984962560', 'author': 'Alex Schwab', 'author_title': 'IT-Consultant @Finanz Informatik', 'source': 'LinkedIn', 'url': 'https://www.linkedin.com/posts/alex-schwab0000_fiforum-finanzinformatik-networking-share-7522962457984962560-pny8/', 'text': 'Das FI-Forum 2026 von der Finanz Informatik ist ab morgen in vollem Gange! 🚀 Ich freue mich riesig darauf, mit unseren geschätzten Kunden sowie vielen spannenden Kolleginnen und Kollegen auf dem FI-Forum in Frankfurt zu netzwerken … Ich bin bei Arbeitswelten auf dem Messegelände unterwegs.', 'created_at': '2026-11-02T10:06:59Z', 'likes': 6, 'comments': 0, 'category': 'Mitarbeiter-Ankündigung', 'sentiment': 'positive', 'confidence': 0.86, 'severity': 'low', 'summary': 'FI-Mitarbeiter freut sich auf Networking, unterwegs bei Arbeitswelten auf dem Messegelände.', 'themes': ['Arbeitswelten', 'Networking', '#TeamFI'], 'verified': True},
    {'id': 'li_7522962428943290368', 'author': 'Carsten Gierke', 'author_title': 'Deputy Head of Client Unit Sparkassen-Finanzgruppe, Sopra Steria', 'source': 'LinkedIn', 'url': 'https://www.linkedin.com/posts/carsten-gierke-524295227_fiforum2026-soprasteria-sparkassen-share-7522962428943290368-mUCk/', 'text': 'Morgen beginnt das FI-Forum 2026 der Finanz Informatik in Frankfurt. Ab 10:00 Uhr sind wir an Stand 13 für Sie da. Um 14:45 Uhr hält Lisa Minhöfer in Raum MC3 ihre Masterclass „Es war einmal ein Risiko – (k)ein Märchen von PPS-IKS“ … Ein wirksames internes Kontrollsystem setzt früher an.', 'created_at': '2026-11-02T10:06:52Z', 'likes': 9, 'comments': 0, 'category': 'Speaker / Vortrag', 'sentiment': 'positive', 'confidence': 0.88, 'severity': 'low', 'summary': 'Sopra Steria an Stand 13; Masterclass von Lisa Minhöfer zu PPS-IKS (14:45 Uhr, MC3).', 'themes': ['Sopra Steria', 'PPS-IKS', 'Masterclass'], 'verified': True},
    {'id': 'li_7522958769715318784', 'author': 'Petra von Crailsheim', 'author_title': 'Vorständin bei Ostsächsische Sparkasse Dresden', 'source': 'LinkedIn', 'url': 'https://www.linkedin.com/posts/petra-von-crailsheim-b4a73376_unser-heimvorteil-im-privatkundenvertrieb-ugcPost-7522958769715318784-C-Rk/', 'text': 'Unser Heimvorteil im Privatkundenvertrieb ist unsere große Chance - mehr in unserem Panel auf dem FI-Forum 2026 mit Claudia Lensker, Sabine Schölzel und Nancy Plaßmann am Mittwoch, den 04.11. um 14 Uhr in der Arena.', 'created_at': '2026-11-02T09:52:20Z', 'likes': 10, 'comments': 0, 'category': 'Speaker / Vortrag', 'sentiment': 'positive', 'confidence': 0.88, 'severity': 'low', 'summary': 'Panel „Heimvorteil Kundennähe“ zum Privatkundenvertrieb am 4.11., 14 Uhr, Arena (Reshare Sabine Schölzel).', 'themes': ['Heimvorteil', 'Privatkundenvertrieb', 'Panel'], 'verified': True},
