    {'id': 'li_7522944903212023808', 'author': 'inasys', 'author_title': 'Unternehmen', 'source': 'LinkedIn', 'url': 'https://www.linkedin.com/posts/morgen-startet-das-fi-forum-2026-und-jetzt-share-7522944903212023808-4zjA/', 'text': 'Morgen startet das FI-Forum 2026 und jetzt sind Sie gefragt! Wie lässt sich KI mit dem Private Banking verbinden? Hype, echte Entlastung oder Gefahr für das persönliche Vertrauen? … Diskutieren Sie mit uns auf dem FI-Forum 2026 an Stand Nr. 9.', 'created_at': '2026-11-02T08:57:14Z', 'likes': 1, 'comments': 1, 'category': 'Aussteller / Teilnahme', 'sentiment': 'positive', 'confidence': 0.85, 'severity': 'low', 'summary': 'Live-Umfrage zu KI im Private Banking; Stand 9.', 'themes': ['KI', 'Private Banking', 'Stand 9'], 'verified': True},
    {'id': 'li_7522945806442610688', 'author': 'Peer Hannig', 'author_title': 'Geschäftsführer der inasys GmbH', 'source': 'LinkedIn', 'url': 'https://www.linkedin.com/posts/peer-hannig_welche-lieb-gewonnene-gewissheit-wir-im-private-ugcPost-7522945806442610688-OIWV/', 'text': 'Welche lieb gewonnene Gewissheit wir im Private Banking hinterfragen sollten, darüber spreche ich in meinem neuen Impuls der Woche mit Birte Quitt, Vorständin der Haspa … Birte Quitt ist auch Teil unserer MasterClass „KI trifft Beratung – Das neue Strategiegespräch im Private Banking“. 4. November 2026, 11:45–12:15 Uhr, MC1.', 'created_at': '2026-11-02T09:00:49Z', 'likes': 3, 'comments': 2, 'category': 'Speaker / Vortrag', 'sentiment': 'positive', 'confidence': 0.85, 'severity': 'low', 'summary': 'MasterClass „KI trifft Beratung“ mit Haspa-Vorständin Birte Quitt am 4.11.', 'themes': ['Private Banking', 'KI', 'Haspa'], 'verified': True},
    {'id': 'li_7522946010806030336', 'author': 'Birk Schweppe', 'author_title': 'Digital Transformation | Innovation | Digital Infrastructure @DSGV', 'source': 'LinkedIn', 'url': 'https://www.linkedin.com/posts/birk-schweppe_fiforum-eudiwallet-dyou-share-7522946010806030336-Gtzo/', 'text': 'Heute. Morgen. Übermorgen. Unter diesem Titel stellt das Digitallabor des DSGV auf dem FI-Forum aus … Ab dem 2. Januar 2027 wird die PIN des Online-Ausweises zur Voraussetzung für d-you … Deshalb kann man bei uns am Stand die PIN direkt zurücksetzen. … EUDIPal, unser Wallet-Forschungsprojekt … vom 3. bis 5. November an Stand 7.', 'created_at': '2026-11-02T09:01:38Z', 'likes': 2, 'comments': 0, 'category': 'Aussteller / Teilnahme', 'sentiment': 'positive', 'confidence': 0.85, 'severity': 'low', 'summary': 'DSGV-Digitallabor (Stand 7): d-you, Online-Ausweis-PIN und EUDI-Wallet-Forschung.', 'themes': ['EUDI-Wallet', 'd-you', 'DSGV'], 'verified': True},
